#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common PolyBench definitions (problem sizes, DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (M, N, etc.)
#include "trmm.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize A and B with the same semantics as the original C init_array().
 *
 * C version:
 *
 *   *alpha = 1.5;
 *   for (i = 0; i < m; i++) {
 *     for (j = 0; j < i; j++) {
 *       A[i][j] = (DATA_TYPE)((i+j) % m)/m;
 *     }
 *     A[i][i] = 1.0;
 *     for (j = 0; j < n; j++) {
 *       B[i][j] = (DATA_TYPE)((n+(i-j)) % n)/n;
 *     }
 *   }
 *
 * Mapping to Halide Buffers:
 *   - A is declared in C as A[m][m] and accessed as A[i][j].
 *     We store it as Buffer A(width=m, height=m) and access as A(j, i).
 *   - B is declared in C as B[m][n] and accessed as B[i][j].
 *     We store it as Buffer B(width=n, height=m) and access as B(j, i).
 */
static void init_array(int m, int n,
                       num_t *alpha,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B) {
    *alpha = static_cast<num_t>(1.5);

    Var i("i"), j("j");
    Func init_A("init_A"), init_B("init_B");

    // Make Expr versions of m and n for use inside Halide expressions.
    Expr m_expr = m;
    Expr n_expr = n;

    // A(i,j):
    //   For j < i:  ( (i + j) % m ) / m
    //   For j == i: 1.0
    //   For j > i:  0.0 (never used by the kernel, but we define it anyway)
    init_A(j, i) =
        select(j < i,
               cast<num_t>(((i + j) % m_expr)) / cast<num_t>(m_expr),
               select(j == i,
                      static_cast<num_t>(1.0),
                      static_cast<num_t>(0.0)));

    // B(i,j): ( (n + (i - j)) % n ) / n
    init_B(j, i) =
        cast<num_t>(((n_expr + (i - j)) % n_expr)) / cast<num_t>(n_expr);

    // -------------------------
    // Scheduling for init_A/B
    // -------------------------
    //
    // We want to:
    //   - Make j (the column index) the innermost loop to match the
    //     underlying row-major storage (dimension 0 is contiguous).
    //   - Vectorize across j for good SIMD utilization.
    //   - Parallelize across rows (i) to use multiple cores.
    //
    // We query a reasonable vector width from the host Target so this
    // adapts to AVX2/AVX-512/etc.
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    Var jo("jo"), ji("ji");

    init_A
        .reorder(j, i)                 // j fastest varying, i outer
        .split(j, jo, ji, vec_width)   // j = jo * vec_width + ji
        .parallel(i)                   // parallel over rows
        .vectorize(ji);                // SIMD across columns

    init_B
        .reorder(j, i)
        .split(j, jo, ji, vec_width)
        .parallel(i)
        .vectorize(ji);

    // Realize directly into the user-provided buffers.
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem sizes (compile-time constants from PolyBench headers)
    int m = M;
    int n = N;

    // Scalars and arrays
    num_t alpha;
    // Buffer layout: width = number of columns, height = number of rows
    // A: M x M  -> Buffer(m, m) accessed as A(j, i) == A[i][j] in C
    // B: M x N  -> Buffer(n, m) accessed as B(j, i) == B[i][j] in C
    Buffer<num_t, 2> A(m, m);
    Buffer<num_t, 2> B(n, m);

    // Initialize data
    init_array(m, n, &alpha, A, B);

    // Halide ImageParams corresponding to A and B (read-only views)
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    A_param.set(A);
    B_param.set(B);

    // Vars
    Var i("i"), j("j");

    // Reduction domain over k in [0, m)
    RDom k(0, m, "k");

    // ----------------------------------------
    // Triangular matrix-matrix multiply TRMM
    // ----------------------------------------
    //
    // Original kernel:
    //
    // for (i = 0; i < M; i++)
    //   for (j = 0; j < N; j++) {
    //     for (k = i+1; k < M; k++)
    //       B[i][j] += A[k][i] * B[k][j];
    //     B[i][j] = alpha * B[i][j];
    //   }
    //
    // Dependency analysis shows:
    //   - All reads B[k][j] use the *original* B (different row from the one
    //     currently being written), so there is no loop-carried dependence
    //     across i or j.
    //
    // Thus we can express the final value as:
    //
    //   B_out[i][j] = alpha * ( B_in[i][j] +
    //                           sum_{k = i+1..M-1} A[k][i] * B_in[k][j] )
    //
    // Mapping indices to Halide (remember Buffer(width, height) -> (x, y)):
    //   A[k][i]  -> A_param(i, k)
    //   B[k][j]  -> B_param(j, k)
    //   B[i][j]  -> B_param(j, i)
    //
    // We implement "k from i+1..M-1" via a select inside a reduction over
    // k in [0..M-1], masking out any terms with k <= i.
    Func trmm("trmm");

    Expr alpha_expr = Expr(alpha);
    Expr zero = cast<num_t>(Expr(0));

    trmm(j, i) = alpha_expr *
                 (B_param(j, i) +
                  sum(select(k > i,
                             A_param(i, k) * B_param(j, k),
                             zero)));

    // -------------------------
    // Scheduling for TRMM
    // -------------------------
    //
    // The output is dense MxN. There are no cross-(i,j) dependencies,
    // so we can:
    //   - Make j (columns) the innermost dimension to get contiguous
    //     memory access on B and B_result (dim 0 is contiguous).
    //   - Vectorize along j to exploit SIMD.
    //   - Parallelize across i (rows) to utilize all CPU cores.
    //
    // Note: the internal reduction over k will be computed per (i,j)
    // element; vectorizing j causes Halide to compute a SIMD vector of
    // partial sums for each set of columns, which is exactly what we want.
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    Var jo("jo"), ji("ji");

    trmm
        .reorder(j, i)                 // i outer, j inner (row-major)
        .split(j, jo, ji, vec_width)   // tile columns for vectorization
        .parallel(i)                   // parallel over rows
        .vectorize(ji);                // SIMD across columns inside a tile

    // Compile the kernel to machine code for the host target
    trmm.compile_jit(target);

    // Output buffer for the result (same logical layout as B)
    Buffer<num_t, 2> B_result(n, m);

    // Time the execution (only the actual kernel run, JIT is pre-done)
    auto start = std::chrono::high_resolution_clock::now();

    trmm.realize(B_result);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result to avoid dead-code elimination
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // Remember: B_result(jj, ii) == B[ii][jj] in the original C code
                std::cerr << B_result(jj, ii) << '\n';
            }
        }
    }

    // Print elapsed time in seconds
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
