    // which are stored contiguously in memory (dimension 0).
    Target target = get_jit_target_from_environment();
    const int vec_width = natural_vector_size(type_of<num_t>(), target);

    Var io_A("io_A"), ii_A("ii_A");
    init_A
        .bound(j, 0, m)
        .bound(i, 0, m)
        .split(i, io_A, ii_A, 64)   // tiles of 64 rows
        .parallel(io_A)             // parallel over row-tiles
        .vectorize(j, vec_width);   // vectorize across contiguous columns

    Var io_B("io_B"), ii_B("ii_B");
    init_B
        .bound(j, 0, n)
        .bound(i, 0, m)
        .split(i, io_B, ii_B, 64)
        .parallel(io_B)
        .vectorize(j, vec_width);

    init_A.realize(A, target);
    init_B.realize(B, target);
