    const int tile_i = 32;                  // rows per tile
    const int tile_j = vec_width * 8;       // columns per tile (8 vectors)

    Var jo("jo"), ji("ji"), io("io"), ii("ii");

    trmm
        .bound(j, 0, n)
        .bound(i, 0, m)
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        .vectorize(ji, vec_width)
        .parallel(io);   // parallel over row-tiles

    // Compile the kernel to machine code for the chosen target
    trmm.compile_jit(target);

    // Output buffer for the result (same logical layout as B)
    Buffer<num_t, 2> B_result(n, m);

    // Time the execution
    auto start = std::chrono::high_resolution_clock::now();

    trmm.realize(B_result, target);

    auto end = std::chrono::high_resolution_clock::now();
